(ns episodes.live-spec
  (:require [speclj.core :refer :all]
            [gherclj.core :as g]
            [gherclj.lifecycle :as lifecycle]
            [isaac.config.config-steps :as config-steps]
            [isaac.episodes.episode-steps :as episode-steps]
            [isaac.foundation.cli-steps :as cli-steps]
            [isaac.foundation.fs-steps :as fs-steps]
            [isaac.foundation.harness-config-steps :as harness-config-steps]
            [isaac.foundation.log-steps :as log-steps]
            [isaac.session.session-steps :as session-steps]
            [isaac.tool.tools-steps :as tools-steps]))

(describe "Episodes — live (policy + lifecycle)"

  (around [it]
    (binding [g/*state* (atom {})]
      (lifecycle/run-before-feature-hooks!)
      (try
        (it)
        (finally
          (lifecycle/run-after-feature-hooks!)))))

  (around [it]
    (binding [g/*state* (atom @g/*state*)]
      (lifecycle/run-before-scenario-hooks!)
      (try
        (it)
        (finally
          (lifecycle/run-after-scenario-hooks!)))))

  (it "first prompt on an episode crew opens an episode"
    ;; Given default Grover setup  (episodes/live.feature:13)
    (g/with-step* "Given default Grover setup" "episodes/live.feature" 13 (fn [] (isaac.session.session-steps/default-grover-setup)))
    ;; Given the isaac EDN file "config/crew/cordelia.edn" exists with:  (episodes/live.feature:18)
    ;;   | path | value |  (episodes/live.feature:19)
    ;;   | model | echo |  (episodes/live.feature:20)
    ;;   | soul | You are Cordelia |  (episodes/live.feature:21)
    ;;   | session-policy | episodes |  (episodes/live.feature:22)
    (g/with-step* "Given the isaac EDN file \"config/crew/cordelia.edn\" exists with:" "episodes/live.feature" 18 (fn [] (isaac.foundation.fs-steps/isaac-edn-file-exists "config/crew/cordelia.edn" {:headers ["path" "value"], :rows [["model" "echo"] ["soul" "You are Cordelia"] ["session-policy" "episodes"]], :header-line 19, :row-lines [20 21 22]})))
    ;; And the following model responses are queued:  (episodes/live.feature:23)
    ;;   | type | content | model |  (episodes/live.feature:24)
    ;;   | text | Charted, keep west | echo |  (episodes/live.feature:25)
    (g/with-step* "And the following model responses are queued:" "episodes/live.feature" 23 (fn [] (isaac.session.session-steps/responses-queued {:headers ["type" "content" "model"], :rows [["text" "Charted, keep west" "echo"]], :header-line 24, :row-lines [25]})))
    ;; When isaac is run with "prompt -m 'Chart the reef passage' --session reef-chat --crew cordelia"  (episodes/live.feature:26)
    (g/with-step* "When isaac is run with \"prompt -m 'Chart the reef passage' --session reef-chat --crew cordelia\"" "episodes/live.feature" 26 (fn [] (isaac.foundation.cli-steps/isaac-run "prompt -m 'Chart the reef passage' --session reef-chat --crew cordelia")))
    ;; Then the stdout contains "Charted, keep west"  (episodes/live.feature:27)
    (g/with-step* "Then the stdout contains \"Charted, keep west\"" "episodes/live.feature" 27 (fn [] (isaac.foundation.cli-steps/stdout-contains "Charted, keep west")))
    ;; And the exit code is 0  (episodes/live.feature:28)
    (g/with-step* "And the exit code is 0" "episodes/live.feature" 28 (fn [] (isaac.foundation.cli-steps/exit-code-is "0")))
    ;; And an episode exists for crew "cordelia" matching:  (episodes/live.feature:29)
    ;;   | key | value |  (episodes/live.feature:30)
    ;;   | id | #"\d{17}" |  (episodes/live.feature:31)
    ;;   | status | open |  (episodes/live.feature:32)
    ;;   | session-id | reef-chat |  (episodes/live.feature:33)
    (g/with-step* "And an episode exists for crew \"cordelia\" matching:" "episodes/live.feature" 29 (fn [] (isaac.episodes.episode-steps/episode-exists-for-crew-matching "cordelia" {:headers ["key" "value"], :rows [["id" "#\"\\d{17}\""] ["status" "open"] ["session-id" "reef-chat"]], :header-line 30, :row-lines [31 32 33]})))
    ;; And the following sessions match:  (episodes/live.feature:34)
    ;;   | id | crew |  (episodes/live.feature:35)
    ;;   | reef-chat | cordelia |  (episodes/live.feature:36)
    (g/with-step* "And the following sessions match:" "episodes/live.feature" 34 (fn [] (isaac.session.session-steps/sessions-match {:headers ["id" "crew"], :rows [["reef-chat" "cordelia"]], :header-line 35, :row-lines [36]})))
    ;; And that episode's backing session has transcript matching:  (episodes/live.feature:37)
    ;;   | type | message.role | message.content |  (episodes/live.feature:38)
    ;;   | message | user | Chart the reef passage |  (episodes/live.feature:39)
    ;;   | message | assistant | Charted, keep west |  (episodes/live.feature:40)
    (g/with-step* "And that episode's backing session has transcript matching:" "episodes/live.feature" 37 (fn [] (isaac.episodes.episode-steps/that-episode-backing-session-has-transcript-matching {:headers ["type" "message.role" "message.content"], :rows [["message" "user" "Chart the reef passage"] ["message" "assistant" "Charted, keep west"]], :header-line 38, :row-lines [39 40]}))))

