  (it "compaction closes the episode and seeds the successor"
    ;; Given default Grover setup  (episodes/live.feature:13)
    (g/with-step* "Given default Grover setup" "episodes/live.feature" 13 (fn [] (isaac.session.session-steps/default-grover-setup)))
    ;; Given the isaac EDN file "config/crew/cordelia.edn" exists with:  (episodes/live.feature:149)
